#[path = "solution.rs"]
mod solution;

use solution::{Phase, PhaseMachine};

#[test]
fn construction_normalizes_zero_duration_phases() {
    assert_eq!(PhaseMachine::new(5, 7), PhaseMachine { phase: Phase::Warmup, remaining_ms: 5 });
    assert_eq!(PhaseMachine::new(0, 7), PhaseMachine { phase: Phase::Active, remaining_ms: 7 });
    assert_eq!(PhaseMachine::new(0, 0), PhaseMachine { phase: Phase::Finished, remaining_ms: 0 });
}

#[test]
fn partial_and_exact_advances_have_deterministic_transitions() {
    let mut machine = PhaseMachine::new(10, 20);
    assert_eq!(machine.advance(0), vec![]);
    assert_eq!(machine.remaining_ms, 10);
    assert_eq!(machine.advance(4), vec![]);
    assert_eq!(machine, PhaseMachine { phase: Phase::Warmup, remaining_ms: 6 });
    assert_eq!(machine.advance(6), vec![Phase::Active]);
    assert_eq!(machine, PhaseMachine { phase: Phase::Active, remaining_ms: 20 });
    assert_eq!(machine.advance(19), vec![]);
    assert_eq!(machine.remaining_ms, 1);
    assert_eq!(machine.advance(1), vec![Phase::Finished]);
    assert!(machine.is_finished());
    assert_eq!(machine.remaining_ms, 0);
}

#[test]
fn one_call_can_cross_all_boundaries_and_ignores_surplus() {
    let mut machine = PhaseMachine::new(2, 3);
    assert_eq!(machine.advance(5), vec![Phase::Active, Phase::Finished]);
    assert_eq!(machine.phase, Phase::Finished);
    assert_eq!(machine.remaining_ms, 0);
    assert_eq!(machine.advance(u64::MAX), vec![]);
}

#[test]
fn maximum_durations_do_not_overflow() {
    let mut machine = PhaseMachine::new(u64::MAX, u64::MAX);
    assert_eq!(machine.advance(u64::MAX), vec![Phase::Active]);
    assert_eq!(machine.remaining_ms, u64::MAX);
    assert_eq!(machine.advance(u64::MAX), vec![Phase::Finished]);
    assert!(machine.is_finished());

    let mut active = PhaseMachine::new(0, u64::MAX);
    assert_eq!(active.advance(u64::MAX), vec![Phase::Finished]);
}

